import{_ as a,o as e,c as n,a2 as r}from"./chunks/framework.RycU2wFZ.js";const u=JSON.parse('{"title":"AgentPay 核心任务全景规划与技术演进路线图 (Master Roadmap)","description":"","frontmatter":{},"headers":[],"relativePath":"roadmap/index.md","filePath":"roadmap/index.md"}'),o={name:"roadmap/index.md"};function s(i,t,l,d,g,h){return e(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="agentpay-核心任务全景规划与技术演进路线图-master-roadmap" tabindex="-1">AgentPay 核心任务全景规划与技术演进路线图 (Master Roadmap) <a class="header-anchor" href="#agentpay-核心任务全景规划与技术演进路线图-master-roadmap" aria-label="Permalink to &quot;AgentPay 核心任务全景规划与技术演进路线图 (Master Roadmap)&quot;">​</a></h1><blockquote><p><strong>版本</strong>：v2.0.0 (唯一正式发布基线)<br><strong>状态</strong>：<strong>官方主线规划 (Approved Master Plan)</strong><br><strong>核心定位</strong>：<strong>企业级 AI 行为审计与资金防火墙网关 (AI Agent Gateway &amp; FinOps)</strong><br><strong>说明</strong>：本文档为 AgentPay 全局唯一技术路线图，全面聚焦于企业生产环境中大模型与 AI Agent 的行为审计、资金防火墙、组织树状配额切分、人在回路 (HITL) 协同审批、合规法币预付与发票闭环，<strong>以生产级架构完备性与企业级交付为唯一标准</strong>。</p></blockquote><hr><h2 id="_1-全局愿景与核心架构定位-core-vision-architecture" tabindex="-1">1. 全局愿景与核心架构定位 (Core Vision &amp; Architecture) <a class="header-anchor" href="#_1-全局愿景与核心架构定位-core-vision-architecture" aria-label="Permalink to &quot;1. 全局愿景与核心架构定位 (Core Vision &amp; Architecture)&quot;">​</a></h2><p>在企业级大模型与智能体规模化落地过程中，底层的支付与结算通道（微信支付、支付宝、企业对公转账、银企直联）是可插拔的基础设施。AgentPay 最核心且不可替代的护城河在于：<strong>架设在“AI 智能与推理”与“外部资金与数据资源”之间的「金融防火墙（Financial Firewall）」、「防悬挂三态状态机（Hold/Capture/Release）」以及「不可篡改行为审计黑匣子」</strong>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                               ┌────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>                               │     AgentPay: 企业级 AI 行为审计与资金防火墙网关 (FinOps) │</span></span>
<span class="line"><span>                               └───────────────────────────┬────────────────────────────┘</span></span>
<span class="line"><span>              ┌────────────────────────────┬───────────────┴───────────────┬────────────────────────────┐</span></span>
<span class="line"><span>              ▼                            ▼                               ▼                            ▼</span></span>
<span class="line"><span>     【模块一：企业内控与安全】      【模块二：FinOps与财务闭环】    【模块三：微计费与高并发清算】   【模块四：生态与全栈开发】</span></span>
<span class="line"><span>     • 飞书/企微/钉钉 HITL 审批      • 租户/部门/项目树状预算切分      • 毫秒级 Token 流式微计费       • MCP 协议原生支付中间件</span></span>
<span class="line"><span>     • 独立进程外 Sidecar 防御       • 微信/支付宝企业预付充值        • 高频批量记账缓冲与聚合落盘     • 与 Langfuse 深度联动共生</span></span>
<span class="line"><span>     • 云端 KMS / 国密 HSM 硬件签名  • 严防“二清”持牌合规分账         • 分布式集群与多节点一致性       • Java/Spring Boot Starter</span></span>
<span class="line"><span>     • 行为异动实时检测与自适应熔断  • 数电发票与对账单流水导出       • 五重对账巡检与自动平账调度     • 推进行业行为审计协议标准</span></span></code></pre></div><table tabindex="0"><thead><tr><th>维度</th><th><strong>企业级 AI 行为审计与资金防火墙 (Enterprise FinOps Gateway)</strong></th></tr></thead><tbody><tr><td><strong>核心定位</strong></td><td><strong>AI Agent Gateway &amp; FinOps Financial Firewall</strong></td></tr><tr><td><strong>主要客群</strong></td><td>接入生产环境的政企客户、Agent 开发者、SaaS 服务商、企业内部 IT 与财务平台</td></tr><tr><td><strong>解决痛点</strong></td><td>预防 Agent 死循环刷爆预算、财务分摊一团烂账、合规审计定责困难、失控调用造成资产损失</td></tr><tr><td><strong>资金通道</strong></td><td>人民币预付虚拟账本（6 位微单位）、企业对公汇款凭证审核、微信支付/支付宝对接、数电发票直连</td></tr></tbody></table><hr><h2 id="_2-四大核心任务模块详情" tabindex="-1">2. 四大核心任务模块详情 <a class="header-anchor" href="#_2-四大核心任务模块详情" aria-label="Permalink to &quot;2. 四大核心任务模块详情&quot;">​</a></h2><h3 id="模块一-企业级安全防御与人在回路-enterprise-security-hitl" tabindex="-1">模块一：企业级安全防御与人在回路（Enterprise Security &amp; HITL） <a class="header-anchor" href="#模块一-企业级安全防御与人在回路-enterprise-security-hitl" aria-label="Permalink to &quot;模块一：企业级安全防御与人在回路（Enterprise Security &amp; HITL）&quot;">​</a></h3><h4 id="_1-1-办公协同与人在回路-human-in-the-loop-hitl-审批" tabindex="-1">1.1 办公协同与人在回路（Human-in-the-Loop, HITL）审批 <a class="header-anchor" href="#_1-1-办公协同与人在回路-human-in-the-loop-hitl-审批" aria-label="Permalink to &quot;1.1 办公协同与人在回路（Human-in-the-Loop, HITL）审批&quot;">​</a></h4><ul><li><strong>三级风控梯度</strong>： <ul><li><strong>小额</strong>（$\\le$ 阈值）：本地策略毫秒级极速放行；</li><li><strong>中大额</strong>：触发外部协作平台人工审批；</li><li><strong>超大额</strong>：触发单笔硬顶阻断（<code>SINGLE_TX_CAP_EXCEEDED</code>）。</li></ul></li><li><strong>402 异步挂起与解挂机制</strong>：网关返回 <code>402 Payment Required</code> 与 <code>approval_id</code>，避免 HTTP 长连接阻塞，后台异步向负责人的<strong>飞书 / 企业微信 / 钉钉</strong>推送富文本审批卡片。</li><li><strong>移动端一键放行</strong>：审批卡片显示 Agent 身份、触发意图、预计消耗与归属部门；负责人点击批准后，客户端 SDK 自动携带凭证重放，网关原子执行 Hold 冻结与后续调用。</li></ul><h4 id="_1-2-进程外隔离-sidecar-守护进程-防御-n6-威胁" tabindex="-1">1.2 进程外隔离 Sidecar 守护进程（防御 N6 威胁） <a class="header-anchor" href="#_1-2-进程外隔离-sidecar-守护进程-防御-n6-威胁" aria-label="Permalink to &quot;1.2 进程外隔离 Sidecar 守护进程（防御 N6 威胁）&quot;">​</a></h4><ul><li><strong>痛点解决</strong>：在现有嵌入式 SDK 模式下，LLM 运行时与 SDK 共享宿主进程。若工具具备任意代码执行能力，存在进程内存窃取或绕过拦截器的风险。</li><li><strong>架构方案</strong>：将金融防火墙与签名器下沉为独立的<strong>本地 Sidecar 守护进程</strong>（或轻量 Docker/Unix Domain Socket），以独立低权限 OS 用户运行，主 Agent 仅能通过 IPC 发起支付意图。</li></ul><h4 id="_1-3-云端-kms-与国密-hsm-硬件安全签名-防御-n1-威胁" tabindex="-1">1.3 云端 KMS 与国密 HSM 硬件安全签名（防御 N1 威胁） <a class="header-anchor" href="#_1-3-云端-kms-与国密-hsm-硬件安全签名-防御-n1-威胁" aria-label="Permalink to &quot;1.3 云端 KMS 与国密 HSM 硬件安全签名（防御 N1 威胁）&quot;">​</a></h4><ul><li><strong>核心功能</strong>：买方与网关凭据脱离本地明文存储与环境变量。</li><li><strong>集成支持</strong>： <ul><li>接入阿里云 KMS、腾讯云 KMS、AWS KMS、Google Cloud KMS；</li><li>针对金融与政企合规客户，支持国密硬件加密机（HSM）与 PKCS#11 硬件令牌进行签名。</li></ul></li></ul><h4 id="_1-4-智能行为异动检测与自适应熔断-anomaly-detection" tabindex="-1">1.4 智能行为异动检测与自适应熔断（Anomaly Detection） <a class="header-anchor" href="#_1-4-智能行为异动检测与自适应熔断-anomaly-detection" aria-label="Permalink to &quot;1.4 智能行为异动检测与自适应熔断（Anomaly Detection）&quot;">​</a></h4><ul><li><strong>频次与分布建模</strong>：在传统固定 RPM 熔断之外，构建基于滑动窗口的请求频次与单价消耗基线模型。</li><li><strong>渐进式响应</strong>：首次偏离基线触发警告日志；持续偏离自动切断流量，并将该 Agent 的 API Key 降级或置入临时观察区。</li></ul><hr><h3 id="模块二-ai-finops、合规法币与企业财务闭环-finops-compliance" tabindex="-1">模块二：AI FinOps、合规法币与企业财务闭环（FinOps &amp; Compliance） <a class="header-anchor" href="#模块二-ai-finops、合规法币与企业财务闭环-finops-compliance" aria-label="Permalink to &quot;模块二：AI FinOps、合规法币与企业财务闭环（FinOps &amp; Compliance）&quot;">​</a></h3><h4 id="_2-1-树状组织多层配额体系" tabindex="-1">2.1 树状组织多层配额体系 <a class="header-anchor" href="#_2-1-树状组织多层配额体系" aria-label="Permalink to &quot;2.1 树状组织多层配额体系&quot;">​</a></h4><ul><li><strong>四级成本切分架构</strong>：<strong>租户（企业/组织） $\\to$ 事业群/部门 $\\to$ 项目组 $\\to$ 具体 Agent</strong>。</li><li><strong>配额管理</strong>：支持“父节点总预算硬顶 + 子节点按月/按季分配额度”；支持预算耗尽自动降级或拦截。</li></ul><h4 id="_2-2-国内合规法币充值体系" tabindex="-1">2.2 国内合规法币充值体系 <a class="header-anchor" href="#_2-2-国内合规法币充值体系" aria-label="Permalink to &quot;2.2 国内合规法币充值体系&quot;">​</a></h4><ul><li><strong>双阶段防“二清”合规路线</strong>： <ul><li><strong>阶段一（自营与平台聚合预付）</strong>：资金入平台对公账户，换算为内部不可提现、不可跨租户互转的虚拟账本微单位，纯属于算力与 API 预售，零金融牌照风险；</li><li><strong>阶段二（多商户撮合清分）</strong>：接入持牌机构（微信电商收付通、支付宝直付通、商业银行专用账户），网关仅下发清分指令，资金不过平台账户。</li></ul></li><li><strong>入账精度换算</strong>：外部渠道以人民币“分”（两位小数）交互，入账边界严格执行 $\\text{amount_base_units} = \\text{payment_minor_amount} \\times 10,000$，转为 6 位微单位整数存储，全程严禁浮点数。</li><li><strong>充值双层幂等防重放</strong>：<code>external_ref</code> 与 <code>topup:{id}</code> 组合唯一索引，防止三方 Webhook 重试造成重复入账。</li></ul><h4 id="_2-3-财务核销、对账单与数电发票集成" tabindex="-1">2.3 财务核销、对账单与数电发票集成 <a class="header-anchor" href="#_2-3-财务核销、对账单与数电发票集成" aria-label="Permalink to &quot;2.3 财务核销、对账单与数电发票集成&quot;">​</a></h4><ul><li><strong>日终自动平账</strong>：自动核对支付渠道账单流水、网关账本变动与上游履约记录。</li><li><strong>合规发票闭环</strong>：支持月度消费账单导出（包含按部门拆分的调用流水），直连数电发票接口，一键开具增值税普票或专票。</li></ul><hr><h3 id="模块三-微计费引擎与分布式清算架构-micro-metering-distributed-settlement" tabindex="-1">模块三：微计费引擎与分布式清算架构（Micro-Metering &amp; Distributed Settlement） <a class="header-anchor" href="#模块三-微计费引擎与分布式清算架构-micro-metering-distributed-settlement" aria-label="Permalink to &quot;模块三：微计费引擎与分布式清算架构（Micro-Metering &amp; Distributed Settlement）&quot;">​</a></h3><h4 id="_3-1-毫秒级-token-流式微计费与动态单价折算" tabindex="-1">3.1 毫秒级 Token 流式微计费与动态单价折算 <a class="header-anchor" href="#_3-1-毫秒级-token-流式微计费与动态单价折算" aria-label="Permalink to &quot;3.1 毫秒级 Token 流式微计费与动态单价折算&quot;">​</a></h4><ul><li><strong>核心逻辑</strong>：流式调用场景下（SSE Chunk-by-Chunk 解析），在传输过程中实时计量 Prompt 与 Completion Token；</li><li><strong>技术实现</strong>： <ul><li>基于模型定价字典动态预估最大额度并在请求前 Hold；</li><li>流式响应结束后，网关根据真实 Token 消耗精确核算（Capture），毫秒级释放多余预留（Release），杜绝额度悬挂与资金浪费。</li></ul></li></ul><h4 id="_3-2-高频批量记账缓冲与聚合落盘-batch-settlement-buffer" tabindex="-1">3.2 高频批量记账缓冲与聚合落盘 (Batch Settlement Buffer) <a class="header-anchor" href="#_3-2-高频批量记账缓冲与聚合落盘-batch-settlement-buffer" aria-label="Permalink to &quot;3.2 高频批量记账缓冲与聚合落盘 (Batch Settlement Buffer)&quot;">​</a></h4><ul><li><strong>适用场景</strong>：面向企业数千并发智能体的高频微额调用场景，降低数据库单笔写入开销。</li><li><strong>技术实现</strong>： <ul><li>网关在本地内存原子验证配额并记录账单事件；</li><li>采用滑动时间窗口与微批量聚合机制，批量事务性写入底层不可变账本（<code>ap_ledger_entry</code>），将数据库 I/O 写入压力降低 90% 以上。</li></ul></li></ul><h4 id="_3-3-高可用分布式网关集群" tabindex="-1">3.3 高可用分布式网关集群 <a class="header-anchor" href="#_3-3-高可用分布式网关集群" aria-label="Permalink to &quot;3.3 高可用分布式网关集群&quot;">​</a></h4><ul><li><strong>分布式配置同步</strong>：将现有基于内存的单机 RCU 升级为基于 Raft 或 Redis/etcd 协同的分布式事件总线，实现跨多实例路由规则、Key 状态与配额的秒级同步；</li><li><strong>五重对账引擎调度器（Five-Way Reconciliation Scheduler）</strong>：独立常驻的离线对账巡检器，跨节点排查并自动平账非终态悬挂订单。</li></ul><hr><h3 id="模块四-开放生态、全语言-sdk-与开源联动-ecosystem-devex" tabindex="-1">模块四：开放生态、全语言 SDK 与开源联动（Ecosystem &amp; DevEx） <a class="header-anchor" href="#模块四-开放生态、全语言-sdk-与开源联动-ecosystem-devex" aria-label="Permalink to &quot;模块四：开放生态、全语言 SDK 与开源联动（Ecosystem &amp; DevEx）&quot;">​</a></h3><h4 id="_4-1-mcp-model-context-protocol-协议原生支持" tabindex="-1">4.1 MCP（Model Context Protocol）协议原生支持 <a class="header-anchor" href="#_4-1-mcp-model-context-protocol-协议原生支持" aria-label="Permalink to &quot;4.1 MCP（Model Context Protocol）协议原生支持&quot;">​</a></h4><ul><li><strong>标价中间件</strong>：为 Anthropic MCP Server 提供开箱即用的支付拦截插件，使任何本地或远程 MCP 工具具备一键声明价格的能力；</li><li><strong>客户端防火墙</strong>：在 MCP Client 端自动注入 AgentPay 金融防火墙，智能解析 Tool Call 入参并进行额度预检。</li></ul><h4 id="_4-2-与开源-observability-langfuse-深度共生" tabindex="-1">4.2 与开源 Observability（Langfuse）深度共生 <a class="header-anchor" href="#_4-2-与开源-observability-langfuse-深度共生" aria-label="Permalink to &quot;4.2 与开源 Observability（Langfuse）深度共生&quot;">​</a></h4><ul><li><strong>定位分工</strong>：明确不重复研发 Prompt 管理工具，与 MIT 协议开源顶流 Langfuse 组成**「AI 运维双子星」**： <ul><li><strong>Langfuse 管“大脑”</strong>：负责 Prompt 追踪、Token/Embedding 监控、LLM 评分与评估；</li><li><strong>AgentPay 管“双手”</strong>：负责拦截外部真实金钱交易、物理切断死循环、保障不可篡改审计定责。</li></ul></li><li><strong>无缝打通</strong>：在 AgentPay 审计流中自动关联 Langfuse 的 <code>trace_id</code> 与 <code>span_id</code>，实现“输入 Prompt $\\to$ 模型思考 $\\to$ 付费调用 $\\to$ 真实扣款”的全链路联合排查。</li></ul><h4 id="_4-3-多语言客户端与卖方中间件生态补全" tabindex="-1">4.3 多语言客户端与卖方中间件生态补全 <a class="header-anchor" href="#_4-3-多语言客户端与卖方中间件生态补全" aria-label="Permalink to &quot;4.3 多语言客户端与卖方中间件生态补全&quot;">​</a></h4><ul><li><strong>Java / Spring Boot Starter</strong>：面向大型金融、电信及政企后端技术栈，提供注解式权限与防火墙 SDK（<code>@AgentPayGuard</code>）；</li><li><strong>Node.js / Web 卖方中间件</strong>：发布 Express、Fastify、NestJS 中间件，供 API 卖方一行代码接入计费与防火墙验证；</li><li><strong>Python / TS SDK 持续演进</strong>：深化与 LangChain、Dify、CrewAI、AutoGen 及 Vercel AI SDK 的深度适配。</li></ul><h4 id="_4-4-推动企业级-ai-行为审计与资金防火墙标准" tabindex="-1">4.4 推动企业级 AI 行为审计与资金防火墙标准 <a class="header-anchor" href="#_4-4-推动企业级-ai-行为审计与资金防火墙标准" aria-label="Permalink to &quot;4.4 推动企业级 AI 行为审计与资金防火墙标准&quot;">​</a></h4><ul><li>提炼企业级 AI 网关的三态状态机规范与 Header 协议；</li><li>推动将支持企业虚拟账本两阶段挑战与人在回路审批的防护标准提交为行业标准规范。</li></ul><hr><h2 id="_3-任务执行优先级矩阵-task-priority-matrix" tabindex="-1">3. 任务执行优先级矩阵 (Task Priority Matrix) <a class="header-anchor" href="#_3-任务执行优先级矩阵-task-priority-matrix" aria-label="Permalink to &quot;3. 任务执行优先级矩阵 (Task Priority Matrix)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>优先级</th><th>任务板块</th><th>交付标志与核心成果</th></tr></thead><tbody><tr><td><strong>P0（近期主线）</strong></td><td><strong>企业协同 HITL + 法币预付闭环</strong></td><td>飞书/企微/钉钉审批卡片打通；微信/支付宝企业预付流水入账；部门多层树状配额切分与级联校验</td></tr><tr><td><strong>P0（近期主线）</strong></td><td><strong>MCP 原生插件 + Langfuse 联动</strong></td><td>MCP Server/Client 官方支付扩展；Langfuse Trace 联合追踪面板</td></tr><tr><td><strong>P1（重要演进）</strong></td><td><strong>流式微计费与高频批量记账缓冲</strong></td><td>流式 SSE Token 精准核算与防悬挂三态释放；高频微额批量聚合入账落盘</td></tr><tr><td><strong>P1（重要演进）</strong></td><td><strong>Java/Spring Boot SDK 与卖方中间件</strong></td><td>完成政企核心生态 Java SDK（<code>@AgentPayGuard</code>）；完善 Node.js 卖方中间件</td></tr><tr><td><strong>P2（架构深化）</strong></td><td><strong>KMS/国密 HSM + 独立 Sidecar 守护</strong></td><td>凭据私钥脱离本地明文存储与环境变量；进程外独立低权限环境拦截恶意代码</td></tr><tr><td><strong>P2（架构深化）</strong></td><td><strong>分布式网关集群与五重对账调度器</strong></td><td>多实例分布式事件总线状态同步；常驻离线对账巡检器排查悬挂订单并自动平账</td></tr><tr><td><strong>P3（生态远景）</strong></td><td><strong>企业私有化套件与行业标准化</strong></td><td>发布私有化开箱套件；推动企业级 AI 行为审计与防火墙行业规范标准草案</td></tr></tbody></table>`,47)])])}const p=a(o,[["render",s]]);export{u as __pageData,p as default};
